#pragma once
static const char CALENDAR_PAGE[]=R"HTML(<h1>班表與鬧鐘</h1><p>選擇月份，點選上班日期，或上傳班表圖片自動填入。確認日期與響鈴時間後儲存。</p><label>月份<input id="month" type="month" min="2024-01" max="2099-12"></label><form id="upload"><label class="upload-box">班表圖片<input id="image" type="file" accept="image/jpeg,image/png,image/webp"></label><button id="recognize" type="submit">辨識並填入月曆</button><button id="cancel" type="button" hidden>取消辨識</button><p id="ai-status" role="status" aria-live="polite">圖片辨識需要網路；無法辨識時仍可直接點選日期。</p></form><div class="calendar" id="weekdays"><span>日</span><span>一</span><span>二</span><span>三</span><span>四</span><span>五</span><span>六</span></div><div class="calendar" id="days"></div><p id="count"></p><p class="help">深色：上班 · 淺色：休假 · 橙色：需要確認。點選日期即可調整。</p><button id="clear" class="secondary" type="button">清除本月上班日</button><h2>上班日響鈴時間</h2><p>每個上班日使用下列時間，最多八個。</p><div id="times"></div><button id="add" class="secondary" type="button">＋ 新增鬧鐘時間</button><p class="help">使用臺灣時間。儲存只更新這個月份，其他月份不變。</p><button id="save" type="button">儲存班表與鬧鐘</button><p id="status" role="status" aria-live="polite"></p><button id="clock" type="button" hidden>使用此手機時間校時</button><p><a href="/display">裝置設定與時鐘校對</a> · <a href="/tailnet">Tailscale 連線</a></p><script>
const nonce='NONCE',month=document.querySelector('#month'),statusEl=document.querySelector('#status'),aiStatus=document.querySelector('#ai-status');let selected=new Set(),review=new Set(),alarmTimes=[],busy=false,dirty=false,loadedMonth='',loadSeq=0,controller=null,mixedTimes=false;
const pad=n=>String(n).padStart(2,'0');
function controls(){for(const id of ['month','clear','add','save','recognize','image'])document.getElementById(id).disabled=busy;document.getElementById('save').disabled=busy||loadedMonth!==month.value;document.querySelector('#cancel').hidden=!controller;draw();drawTimes()}
function draw(){const [y,m]=month.value.split('-').map(Number),grid=document.querySelector('#days');grid.replaceChildren();if(!y||!m)return;for(let i=0;i<new Date(y,m-1,1).getDay();i++)grid.append(document.createElement('span'));for(let day=1;day<=new Date(y,m,0).getDate();day++){const b=document.createElement('button');b.type='button';b.textContent=day;b.className=review.has(day)?'reviewday':selected.has(day)?'workday':'';b.setAttribute('aria-pressed',selected.has(day));b.setAttribute('aria-label',`${m}月${day}日，${review.has(day)?'待確認':selected.has(day)?'上班':'休假'}`);b.disabled=busy;b.onclick=()=>{if(review.delete(day))selected.add(day);else selected.has(day)?selected.delete(day):selected.add(day);dirty=true;draw()};grid.append(b)}document.querySelector('#count').textContent=`${selected.size} 天上班${review.size?' · '+review.size+' 天待確認':''}`}
function drawTimes(){const wrap=document.querySelector('#times');wrap.replaceChildren();alarmTimes.forEach((value,i)=>{const row=document.createElement('div');row.className='time-row';const title=document.createElement('strong');title.textContent='鬧鐘 '+(i+1);row.append(title);const [hour,minute]=value.split(':');for(const [unit,current,max] of [['時',hour,24],['分',minute,60]]){const label=document.createElement('label'),select=document.createElement('select');select.setAttribute('aria-label',`第 ${i+1} 個鬧鐘的${unit}`);for(let n=0;n<max;n++){const o=document.createElement('option');o.value=pad(n);o.textContent=pad(n)+' '+unit;select.append(o)}select.value=current;select.disabled=busy;select.onchange=()=>{const parts=alarmTimes[i].split(':');parts[unit==='時'?0:1]=select.value;alarmTimes[i]=parts.join(':');dirty=true};label.append(select);row.append(label)}const remove=document.createElement('button');remove.className='secondary';remove.type='button';remove.textContent='移除';remove.setAttribute('aria-label',`移除第 ${i+1} 個鬧鐘`);remove.disabled=busy;remove.onclick=()=>{alarmTimes.splice(i,1);dirty=true;drawTimes()};row.append(remove);wrap.append(row)});document.querySelector('#add').disabled=busy||alarmTimes.length>=8;if(!alarmTimes.length){const p=document.createElement('p');p.textContent='尚未設定響鈴時間。';wrap.append(p)}}
async function request(url,options={}){const r=await fetch(url,{...options,headers:{'X-Setup-Nonce':nonce,...options.headers}});const text=await r.text();let data;try{data=JSON.parse(text)}catch{}if(!r.ok)throw Error(typeof data?.detail==='string'?data.detail:typeof data?.error==='string'?data.error:text||'服務暫時無法回應');if(!data)throw Error('服務回應格式無效');return data}
async function load(){const seq=++loadSeq;busy=true;controls();statusEl.textContent='正在讀取班表…';try{const d=await request('/api/local-calendar?month='+encodeURIComponent(month.value));if(seq!==loadSeq)return;selected=new Set(d.days);review.clear();alarmTimes=d.times;mixedTimes=Boolean(d.mixed_times);loadedMonth=month.value;dirty=false;document.querySelector('#clock').hidden=d.clock_ready;statusEl.textContent=d.clock_ready?'點選上班日期，設定響鈴時間後儲存。':'尚未完成校時；班表可先儲存，完成校時後才能準時響鈴。'}catch(e){if(seq!==loadSeq)return;statusEl.textContent='讀取失敗：'+e.message;loadedMonth=''}finally{if(seq===loadSeq){busy=false;controls()}}}
month.onchange=()=>{if(!month.value)return;if(dirty&&!confirm('有尚未儲存的修改，確定切換月份？')){month.value=loadedMonth;return}load()};document.querySelector('#clear').onclick=()=>{selected.clear();review.clear();dirty=true;draw()};document.querySelector('#add').onclick=()=>{if(alarmTimes.length<8){alarmTimes.push('07:00');dirty=true;drawTimes()}};
document.querySelector('#save').onclick=async()=>{if(busy||loadedMonth!==month.value)return;if(mixedTimes&&!confirm('這個月份原本各天有不同響鈴時間。儲存後會把所選上班日統一為下列時間，確定套用？'))return;if(review.size){statusEl.textContent='請先確認橙色日期，再儲存班表。';return}if((selected.size&&!alarmTimes.length)||new Set(alarmTimes).size!==alarmTimes.length){statusEl.textContent='請新增至少一個響鈴時間，且時間不可重複。';return}busy=true;controls();try{await request('/api/local-calendar',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({month:loadedMonth,days:[...selected].sort((a,b)=>a-b),times:alarmTimes})});dirty=false;mixedTimes=false;statusEl.textContent=`已儲存 ${loadedMonth}：${selected.size} 天上班、每天 ${alarmTimes.length} 個鬧鐘。重新開機也會保留。`}catch(e){statusEl.textContent='儲存失敗：'+e.message}finally{busy=false;controls()}};
document.querySelector('#upload').onsubmit=async(e)=>{e.preventDefault();if(busy)return;const file=document.querySelector('#image').files[0];if(!file){aiStatus.textContent='請先選擇班表圖片。';return}if(file.size>10*1024*1024){aiStatus.textContent='圖片不可超過 10 MB。';return}busy=true;controller=new AbortController();controls();const data=new FormData();data.append('file',file);data.append('month',month.value);aiStatus.textContent='正在確認辨識服務連線…';const started=Date.now(),timer=setTimeout(()=>controller?.abort(),60000),progress=setInterval(()=>{aiStatus.textContent='正在辨識班表，已等待 '+Math.floor((Date.now()-started)/1000)+' 秒；可取消後手動選擇日期。'},10000);try{const probeTimer=setTimeout(()=>controller?.abort(),8000);try{const health=await request('/api/health',{signal:controller.signal});if(!health.recognition_ready)throw Error('辨識服務尚未設定')}finally{clearTimeout(probeTimer)}aiStatus.textContent='正在上傳並辨識班表…';const d=await request('/api/import',{method:'POST',headers:{'X-Alarm-UI':'1'},body:data,signal:controller.signal});if(d.month!==month.value||!Array.isArray(d.days))throw Error('辨識月份與選擇月份不符');const work=new Set(),uncertain=new Set();for(const day of d.days){const n=Number(day.date.slice(-2));if(day.classification==='work')work.add(n);else if(day.classification==='review')uncertain.add(n)}selected=work;review=uncertain;dirty=true;aiStatus.textContent=`辨識完成：${work.size} 天上班${uncertain.size?'、'+uncertain.size+' 天待確認':''}。請確認下方日期並儲存。`}catch(e){aiStatus.textContent=e.name==='AbortError'?'辨識已取消或連線逾時，已停止等待；原有日期未變更，可直接調整月曆。':'辨識失敗：'+e.message.replace(/[。\s]+$/,'')+'。原有日期未變更，你仍可直接點選月曆。'}finally{clearTimeout(timer);clearInterval(progress);controller=null;busy=false;controls()}};document.querySelector('#cancel').onclick=()=>controller?.abort();
document.querySelector('#clock').onclick=async()=>{try{await request('/api/local-clock',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({epoch:Math.floor(Date.now()/1000)})});document.querySelector('#clock').hidden=true;statusEl.textContent='已使用此手機／電腦的時間校時。'}catch(e){statusEl.textContent='校時失敗：'+e.message}};
const now=new Date();month.value=now.getFullYear()+'-'+pad(now.getMonth()+1);load();window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
</script>)HTML";
